('21cc3cfe-74d9-4f69-b974-6a053f9e0a71', 'Devotional', 'devotional', 'Devotional Song Lyrics - Bhajan & Spiritual | DJYoungster', 'Explore devotional song lyrics on DJYoungster. Find latest Bhajan, Aarti, Shabad, Sufi, Qawwali & spiritual songs lyrics in Hindi, Punjabi, Tamil & Telugu.', '2026-01-28 10:49:42.073', 'Welcome to the Devotional Lyrics section on DJYoungster, your ultimate destination for spiritual and religious song lyrics. Explore our collection of Bhajan, Aarti, Shabad, Sufi, Qawwali, and devotional songs in Hindi, Punjabi, Tamil, Telugu, and other regional languages to connect with divine music.', '/uploads/1771411196910-devotional.webp'),
('3c46ffb0-4b61-4fa3-830e-142541a89451', 'Instagram Viral', 'instagram-viral', NULL, NULL, '2026-02-18 09:58:47.086', 'Discover lyrics of the hottest Instagram viral songs trending on Reels and Stories. Get full lyrics of viral hits in Hindi, Punjabi, and more — the songs everyone\'s using right now!', '/uploads/1771412709052-ig.webp'),
('45763209-ce60-491b-a82e-dd1edf283df2', 'Telugu', 'telugu', 'Telugu Song Lyrics – Latest & Classic Telugu Songs | DJYoungster', 'Explore the best Telugu song lyrics on DJYoungster. Find lyrics from latest Tollywood hits, classic Telugu movies, and trending songs. Read, create Instagram stories & reels with your favorite Telugu lyrics – free!', '2026-02-19 23:13:00.822', NULL, NULL),
