INSERT INTO `Movie` (`id`, `title`, `slug`, `year`, `director`, `posterUrl`, `description`, `cast`, `producer`, `musicDirector`, `writer`, `genre`, `language`, `metaTitle`, `metaDescription`, `createdAt`) VALUES
('0de0efac-f1a7-4b4e-82f5-ec27e58f16a4', 'Moonwalk', 'moonwalk', 2026, NULL, NULL, 'A vibrant Tamil musical entertainer following the journey of close friends who celebrate life through music and dance. Starring Prabhu Deva and A.R. Rahman, the film is slated for a Summer 2026 release.', ' Prabhu Deva, A.R. Rahman', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-05 08:08:37.175'),
('232449c0-f34d-4214-be50-aa82e339cb03', 'Sarvam Maya', 'sarvam-maya', 2025, 'Akhil Sathyan', '/uploads/1770853735301-Sarvam-Maya-Potrait-Malayalam-1769712560.webp', 'Sarvam Maya is a 2025 Malayalam supernatural romantic comedy directed by Akhil Sathyan, starring Nivin Pauly and Riya Shibu, released on 25 December 2025 with music by Justin Prabhakaran. The film tells the story of an atheist priest who encounters a ghost, leading to a heartfelt journey of faith, love, and self-discovery — earning a 95% score on Rotten Tomatoes and becoming 4th highest-grossing Malayalam films of all time. If you\'re looking for Sarvam Maya songs lyrics, the soulful soundtrack composed by Justin Prabhakaran perfectly complements the film\'s warm and emotional tone. (Streaming from 30 January 2026 on JioHotstar.)', 'Nivin Pauly, Riya Shibu, Aju Varghese, Preity Mukhundhan, Janardhanan, Althaf Salim, Vineeth, Raghunath Paleri, Madhu Wariar', 'Ajayya Kumar, Rajeev Menon', 'Justin Prabhakaran', 'Akhil Sathyan', 'Supernatural Romantic Comedy', 'Malayalam', NULL, NULL, '2026-02-11 22:56:42.556'),
('28e820d2-7c7b-439d-8829-b38dfde39b47', 'Wild Tiger Safari', 'wild-tiger-safari', 2026, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Wild Tiger Safari (2026) Songs Lyrics - DJYoungster', 'Explore Wild Tiger Safari movie song lyrics with meanings and translations on DJYoungster.', '2026-02-23 12:10:15.505'),
('41f7b34e-9dae-45fe-beaf-198966aff7e6', 'O\'Romeo', 'o-romeo', 2026, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-05 15:04:27.342'),
('470fe361-8ca0-4a84-bfac-88369eb93a77', 'Ishqa\'n De Lekhe', 'ishqa-n-de-lekhe', 2026, 'Manvir Brar', '/uploads/1771576029231-MV5BNWU5NWRhY2ItZWY2Yi00MDg2LTg5NWYtMzE4ODFiNDQ2YjkyXkEyXkFqcGc-V1-FMjpg-UX1000.webp', 'Ishqa\'n De Lekhe – an upcoming Punjabi romantic film starring Gurnam Bhullar and Isha Malviya – is all set to win hearts with its powerful tale of love, longing, and raw emotions. An intense love story brought to life through soulful storytelling, gripping drama, and unforgettable performances. With Gurnam Bhullar stepping into a fresh, compelling avatar and Isha Malviya delivering a captivating screen presence, Ishqa\'n De Lekhe promises to be a landmark addition to Punjabi cinema.', 'Gurnam Bhullar, Isha Malviya, Rana Ranbir, Mintu Kappa, Balwinder Bullet, Gurleen Chopra, Jasbir Gill, Mohni Toor, Babar Khan', 'Gurnam Bhullar', NULL, 'Jassi Lohka', NULL, 'Punjabi', 'Ishqa\'n De Lekhe (2026) Songs Lyrics - DJYoungster', 'Explore Ishqa\'n De Lekhe movie song lyrics with meanings and translations on DJYoungster.', '2026-02-20 08:21:52.837'),
('53fa5a6d-00f5-470e-9bfc-62a62cc067d0', 'Gandhi Talks', 'gandhi-talks', 2026, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-05 08:23:18.887'),
('5f730dae-40e5-449e-9e1c-0e0b9a2c15c0', 'Do Deewane Seher Mein', 'do-deewane-seher-mein', 2026, 'Ravi Udyawar', 'https://m.media-amazon.com/images/M/MV5BNzQ2MmEyNGMtYTMyYS00YTUwLTg5YjYtYWUwN2I5M2JiMzhiXkEyXkFqcGc@._V1_.jpg', 'Two socially awkward millennials in Mumbai find love while struggling with self-acceptance. As they battle insecurities and societal pressure, their journey takes them from city chaos to mountain serenity.', 'Siddhant Chaturvedi, Mrunal Thakur, Ila Arun', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-01-31 06:06:17.748'),
('72ba50ff-e6b9-4971-b319-659e6a54205f', 'dude', 'dude', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'dude Songs Lyrics - DJYoungster', 'Explore dude movie song lyrics with meanings and translations on DJYoungster.', '2026-02-13 11:23:21.922'),
('7d879ea1-5899-44a8-99ac-693a34246b90', 'sirai ', 'sirai', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'sirai  Songs Lyrics - DJYoungster', 'Explore sirai  movie song lyrics with meanings and translations on DJYoungster.', '2026-02-13 11:30:24.755'),
('8bed7661-08b7-407a-9e01-d5c64bf05b12', 'Fugly', 'fugly', 2014, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-08 12:42:09.256'),
('8ce60dd2-0e48-4660-a71b-1c971c7a5ba5', 'Revolver Rani', 'revolver-rani', 2014, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-08 12:47:17.758'),
('96642b9f-7195-4adf-8e1c-04381595df6f', 'Battle Of Galwan', 'battle-of-galwan', 2026, 'Apoorva Lakhia', '/uploads/1771514704188-Screenshot-6.webp', 'Battle of Galwan is a compelling cinematic tribute to one of the most intense and defining moments in recent Indian military history — the June 2020 face-off between Indian and Chinese troops in the rugged, unforgiving terrain of the Galwan Valley, Ladakh. At its heart, Battle of Galwan is more than a war film. It is a deeply moving account of patriotism, brotherhood, and the indomitable will of men who chose nation above self, leaving behind a legacy that continues to inspire a generation. Releasing in Cinemas, 17th April 2026.', 'Salman Khan, Chitrangada Singh', NULL, NULL, NULL, 'Action', 'Hindi', 'Battle Of Galwan (2026) Songs Lyrics - DJYoungster', 'Explore Battle Of Galwan movie song lyrics with meanings and translations on DJYoungster.', '2026-02-19 07:39:54.683'),
('9c3ba1e5-4eb4-4795-be0a-f34bf5d54233', 'Border 2', 'border-2', 2026, ' Anurag Singh', 'https://djyoungster.com/uploads/1770117750532-border2.webp', 'Border 2 is a patriotic war film continuing the legacy of Border (1997). It focuses on bravery and sacrifice of Indian soldiers, inspired by real military events. The movie emphasizes nationalism, brotherhood, and the human cost of war.', 'Sunny Deol, Varun Dhawan, Diljit Dosanjh, Sonam Bajwa, Ahan Shetty', NULL, NULL, NULL, 'Action', 'Hindi', NULL, NULL, '2026-02-03 11:16:40.117'),
('a8053f33-966b-4861-b18d-42a6d98d8e7f', 'Subedaar', 'subedaar', 2026, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Subedaar (2026) Songs Lyrics - DJYoungster', 'Explore Subedaar movie song lyrics with meanings and translations on DJYoungster.', '2026-02-23 11:27:11.348'),
('ab780197-4d71-4b20-b33f-cdc8f4bd6a12', 'Tu Yaa Main', 'tu-yaa-main', 2026, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-12 09:44:38.416'),
('b507e26a-0f3b-4a39-9012-62e979cacbbd', 'AA23', 'aa23', 2026, NULL, NULL, 'AA23 is the upcoming action film starring Allu Arjun, marking his first collaboration with director Lokesh Kanagaraj. The movie is expected to be dark, intense, and high-octane, with a strong focus on raw action and powerful character arcs. Backed by top technicians and massive hype, AA23 is shaping up to be one of the most anticipated pan-Indian films.', 'Allu Arjun', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-02 05:53:48.848'),
('bfe01feb-6ba0-4f43-98f6-f1692ad614d1', 'Mirza – The Untold Story ', 'mirza-the-untold-story', 2012, ' Baljit Singh Deo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Mirza – The Untold Story  (2012) Songs Lyrics - DJYoungster', 'Explore Mirza – The Untold Story  movie song lyrics with meanings and translations on DJYoungster.', '2026-02-17 07:50:17.173'),
