('0e0b119b-dff2-4c66-8a67-d0f3570e529f', '🎵 New Lyrics: Let Me Know by T.I.', '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Let Me Know - New Lyrics on DJYoungster</title>\n</head>\n<body style=\"margin: 0; padding: 0; background-color: #f8fafc; font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, sans-serif;\">\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-color: #f8fafc; padding: 40px 20px;\">\n    <tr>\n      <td align=\"center\">\n        <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width: 500px; background-color: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);\">\n\n          <!-- Header -->\n          <tr>\n            <td style=\"background: linear-gradient(135deg, #10b981 0%, #059669 100%); padding: 24px; text-align: center;\">\n              <h1 style=\"margin: 0; color: #ffffff; font-size: 24px; font-weight: 700;\">DJYoungster</h1>\n              <p style=\"margin: 8px 0 0; color: rgba(255,255,255,0.9); font-size: 14px;\">Your Lyrics Destination</p>\n            </td>\n          </tr>\n\n          <!-- Cover Image -->\n          <tr>\n            <td style=\"padding: 24px 24px 16px;\">\n              <img src=\"/uploads/1769600223284-ab67616d0000b2734b4019f6b27b37d6b47af6b9.jpg\" alt=\"Let Me Know\" style=\"width: 100%; height: 200px; object-fit: cover; border-radius: 12px; display: block;\">\n            </td>\n          </tr>\n\n          <!-- Song Details -->\n          <tr>\n            <td style=\"padding: 0 24px;\">\n              <h2 style=\"margin: 0 0 8px; color: #1e293b; font-size: 22px; font-weight: 700;\">Let Me Know</h2>\n              <p style=\"margin: 0 0 16px; color: #64748b; font-size: 14px;\">by T.I. • 2026</p>\n            </td>\n          </tr>\n\n          <!-- Lyrics Excerpt -->\n          <tr>\n            <td style=\"padding: 0 24px;\">\n              <div style=\"background-color: #f8fafc; border-left: 3px solid #10b981; padding: 16px; border-radius: 0 8px 8px 0; margin-bottom: 24px;\">\n                <p style=\"margin: 0; color: #475569; font-size: 15px; line-height: 1.7; font-style: italic; white-space: pre-line;\">intro\nWhoo, whoo, whoo, whoo\nWhoo, whoo, whoo, whoo...</p>\n              </div>\n            </td>\n          </tr>\n\n          <!-- CTA Button -->\n          <tr>\n            <td style=\"padding: 0 24px 32px;\" align=\"center\">\n              <a href=\"https://djyoungster.com/song/let-me-know\" style=\"display: inline-block; background: linear-gradient(135deg, #10b981 0%, #059669 100%); color: #ffffff; text-decoration: none; padding: 14px 32px; border-radius: 50px; font-size: 15px; font-weight: 600; box-shadow: 0 4px 14px rgba(16, 185, 129, 0.4);\">Read Full Lyrics</a>\n            </td>\n          </tr>\n\n          <!-- Divider -->\n          <tr>\n            <td style=\"padding: 0 24px;\">\n              <hr style=\"border: none; border-top: 1px solid #e2e8f0; margin: 0;\">\n            </td>\n          </tr>\n\n          <!-- Footer -->\n          <tr>\n            <td style=\"padding: 24px; text-align: center;\">\n              <p style=\"margin: 0 0 12px; color: #94a3b8; font-size: 13px;\">\n                <a href=\"https://djyoungster.com\" style=\"color: #10b981; text-decoration: none;\">Visit DJYoungster</a>\n                <span style=\"margin: 0 8px;\">•</span>\n                <a href=\"https://djyoungster.com/unsubscribe\" style=\"color: #94a3b8; text-decoration: none;\">Unsubscribe</a>\n              </p>\n              <p style=\"margin: 0; color: #cbd5e1; font-size: 12px;\">© 2026 DJYoungster. All rights reserved.</p>\n            </td>\n          </tr>\n\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>', 'sent', '2026-01-28 14:55:19.755', 1, 0, 0, '2026-01-28 14:55:19.758', '2026-01-28 14:55:19.758'),
('56e7e8f7-9735-4a38-bbdb-8c342c0b07d9', '🎵 New Lyrics: Tevar by Harrdy Sandhu', '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Tevar - New Lyrics on DJYoungster</title>\n</head>\n<body style=\"margin: 0; padding: 0; background-color: #f8fafc; font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, sans-serif;\">\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-color: #f8fafc; padding: 40px 20px;\">\n    <tr>\n      <td align=\"center\">\n        <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width: 500px; background-color: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);\">\n\n          <!-- Header -->\n          <tr>\n            <td style=\"background: linear-gradient(135deg, #10b981 0%, #059669 100%); padding: 24px; text-align: center;\">\n              <h1 style=\"margin: 0; color: #ffffff; font-size: 24px; font-weight: 700;\">DJYoungster</h1>\n              <p style=\"margin: 8px 0 0; color: rgba(255,255,255,0.9); font-size: 14px;\">Your Lyrics Destination</p>\n            </td>\n          </tr>\n\n          <!-- Cover Image -->\n          <tr>\n            <td style=\"padding: 24px 24px 16px;\">\n              <img src=\"https://djyoungster.com/uploads/1769682257085-downloaded.webp\" alt=\"Tevar\" style=\"width: 100%; height: 200px; object-fit: cover; border-radius: 12px; display: block;\">\n            </td>\n          </tr>\n\n          <!-- Song Details -->\n          <tr>\n            <td style=\"padding: 0 24px;\">\n              <h2 style=\"margin: 0 0 8px; color: #1e293b; font-size: 22px; font-weight: 700;\">Tevar</h2>\n              <p style=\"margin: 0 0 16px; color: #64748b; font-size: 14px;\">by Harrdy Sandhu • 2026</p>\n            </td>\n          </tr>\n\n          <!-- Lyrics Excerpt -->\n          <tr>\n            <td style=\"padding: