INSERT INTO `Page` (`id`, `slug`, `title`, `content`, `metaTitle`, `metaDescription`, `isPublished`, `createdAt`, `updatedAt`) VALUES
('02f8731c-5685-45d0-ab47-afd54c3bd4c6', 'about-us', 'About Us', '<section style=\"max-width:680px;width:100%;margin:0px auto;position:relative;overflow:hidden;\">\n\n  <!-- Glow blob -->\n  <div style=\"position:absolute;width:300px;height:300px;pointer-events:none;\"></div>\n\n  <!-- Badge -->\n  <div style=\"display:inline-flex;align-items:center;gap:7px;background:rgba(5,150,105,0.08);border:1px solid rgba(5,150,105,0.25);color:#059669;font-family:\'Inter Tight\',sans-serif;font-size:11px;font-weight:600;letter-spacing:2.5px;text-transform:uppercase;padding:6px 14px;border-radius:50px;margin-bottom:28px;\">\n    <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n    Est. 2023 &bull; Updated January 2026\n  </div>\n\n  <h1 style=\"font-family:\'Inter Tight\',sans-serif;font-size:clamp(32px,6vw,52px);font-weight:800;color:#0f172a;margin:0 0 16px 0;line-height:1.1;letter-spacing:-1.5px;\">About <span style=\"color:#059669;\">Us</span></h1>\n\n  <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:16px;line-height:1.7;margin:0 0 40px 0;\">Welcome to <strong style=\"color:#1e293b;\">DJYoungster</strong>, your ultimate destination for discovering and exploring song lyrics from around the world. Founded with a passion for music and a commitment to connecting people with the songs they love, DJYoungster has grown into one of the most trusted platforms for accurate, comprehensive song lyrics across multiple languages.</p>\n\n  <div style=\"height:1px;background:linear-gradient(to right,transparent,#d1fae5,transparent);margin-bottom:36px;\"></div>\n\n  <!-- 1. Our Mission -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M8 14s1.5 2 4 2 4-2 4-2\"/><line x1=\"9\" y1=\"9\" x2=\"9.01\" y2=\"9\"/><line x1=\"15\" y1=\"9\" x2=\"15.01\" y2=\"9\"/></svg>\n      Our Mission\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">At DJYoungster, our mission is simple: to make song lyrics accessible to everyone, everywhere. We believe that music transcends language barriers, and understanding the words behind your favorite songs deepens your connection to the art. Whether you\'re singing along to the latest Bollywood blockbuster, vibing to trending Punjabi tracks, or exploring classic English hits, we\'re here to help you discover the meaning behind the music.</p>\n  </div>\n\n  <!-- 2. What We Offer -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 18V5l12-2v13\"/><circle cx=\"6\" cy=\"18\" r=\"3\"/><circle cx=\"18\" cy=\"16\" r=\"3\"/></svg>\n      What We Offer\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.6;margin:0 0 16px 0;\">DJYoungster brings together a vast collection of lyrics spanning multiple languages including Hindi, Punjabi, English, Tamil, Telugu, Bhojpuri, Haryanvi, and many more regional languages.</p>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:12px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Extensive Lyrics Database:</strong> We maintain one of the largest collections of song lyrics covering Bollywood, Punjabi music, English songs, South Indian cinema, and regional music from across India. Our database is continuously updated with new releases to ensure you always have access to the latest songs.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Multi-Language Support:</strong> Understanding that India is a land of diverse languages, we provide lyrics in Hindi, Punjabi, English, Tamil, Telugu, Bhojpuri, Haryanvi, Marathi, Bengali, Gujarati, and many other regional languages.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Romanized Lyrics:</strong> For non-native speakers and those who can\'t read scripts like Devanagari, Tamil, or Telugu, we provide romanized (transliterated) versions of lyrics. This allows everyone to sing along, regardless of their familiarity with the original script.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Song Translations:</strong> We offer translations to help you appreciate music in any language. Our translations capture not just the literal meaning but also the emotional essence of the songs.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Artist Information:</strong> Beyond just lyrics, we provide information about singers, music directors, lyricists, and the albums or movies associated with each song, giving you a complete picture of the music you love.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- IG Story & Reel Creator Feature Highlight -->\n  <div style=\"background:linear-gradient(135deg,#0f172a 0%,#1e293b 100%);border:1px solid rgba(5,150,105,0.3);border-radius:16px;padding:28px 28px 24px;margin-bottom:24px;position:relative;overflow:hidden;\">\n    <!-- Decorative gradient orb -->\n    <div style=\"position:absolute;top:-40px;right:-40px;width:160px;height:160px;background:radial-gradient(circle,rgba(5,150,105,0.25) 0%,transparent 70%);pointer-events:none;\"></div>\n    <div style=\"position:absolute;bottom:-30px;left:-30px;width:120px;height:120px;background:radial-gradient(circle,rgba(168,85,247,0.15) 0%,transparent 70%);pointer-events:none;\"></div>\n\n    <div style=\"display:inline-flex;align-items:center;gap:7px;background:rgba(5,150,105,0.15);border:1px solid rgba(5,150,105,0.35);color:#34d399;font-family:\'Inter Tight\',sans-serif;font-size:10px;font-weight:700;letter-spacing:2.5px;text-transform:uppercase;padding:5px 12px;border-radius:50px;margin-bottom:18px;\">\n      <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"/></svg>\n      New Features\n    </div>\n\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:22px;font-weight:800;color:#ffffff;margin:0 0 6px 0;letter-spacing:-0.5px;line-height:1.2;\">Instagram Creator <span style=\"color:#34d399;\">Tools</span></h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:14px;line-height:1.6;margin:0 0 22px 0;\">Turn your favorite lyrics into stunning, shareable Instagram content — directly from DJYoungster.</p>\n\n    <!-- IG Story Creator -->\n    <div style=\"background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.08);border-radius:12px;padding:20px 22px;margin-bottom:14px;\">\n      <div style=\"display:flex;align-items:center;gap:12px;margin-bottom:12px;\">\n        <div style=\"width:40px;height:40px;border-radius:10px;background:linear-gradient(135deg,#f59e0b,#ec4899,#a855f7);display:flex;align-items:center;justify-content:center;flex-shrink:0;\">\n          <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"5\" ry=\"5\"/><path d=\"M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z\"/><line x1=\"17.5\" y1=\"6.5\" x2=\"17.51\" y2=\"6.5\"/></svg>\n        </div>\n        <div>\n          <h3 style=\"font-family:\'Inter Tight\',sans-serif;font-size:16px;font-weight:700;color:#ffffff;margin:0;line-height:1.2;\">IG Story Creator</h3>\n          <p style=\"font-family:\'Inter Tight\',sans-serif;font-size:12px;color:#64748b;margin:2px 0 0 0;\">Lyrics → Beautiful Stories in seconds</p>\n        </div>\n      </div>\n      <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:8px;\">\n        <li style=\"display:flex;align-items:center;gap:8px;font-family:\'Inter Tight\',sans-serif;color:#cbd5e1;font-size:13px;line-height:1.5;\">\n          <svg style=\"flex-shrink:0;\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n          Pick any song lyrics and generate a beautifully styled 9:16 story card\n        </li>\n        <li style=\"display:flex;align-items:center;gap:8px;font-family:\'Inter Tight\',sans-serif;color:#cbd5e1;font-size:13px;line-height:1.5;\">\n          <svg style=\"flex-shrink:0;\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n          Multiple aesthetic themes with gradient backgrounds &amp; dynamic typography\n        </li>\n        <li style=\"display:flex;align-items:center;gap:8px;font-family:\'Inter Tight\',sans-serif;color:#cbd5e1;font-size:13px;line-height:1.5;\">\n          <svg style=\"flex-shrink:0;\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n          Auto-includes song title, artist name &amp; DJYoungster branding\n        </li>\n        <li style=\"display:flex;align-items:center;gap:8px;font-family:\'Inter Tight\',sans-serif;color:#cbd5e1;font-size:13px;line-height:1.5;\">\n          <svg style=\"flex-shrink:0;\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n          One-tap download — ready to post instantly\n        </li>\n      </ul>\n    </div>\n\n    <!-- IG Reel Creator -->\n    <div style=\"background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.08);border-radius:12px;padding:20px 22px;\">\n      <div style=\"display:flex;align-items:center;gap:12px;margin-bottom:12px;\">\n        <div style=\"width:40px;height:40px;border-radius:10px;background:linear-gradient(135deg,#ef4444,#f97316,#eab308);display:flex;align-items:center;justify-content:center;flex-shrink:0;\">\n          <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"23 7 16 12 23 17 23 7\"/><rect x=\"1\" y=\"5\" width=\"15\" height=\"14\" rx=\"2\" ry=\"2\"/></svg>\n        </div>\n        <div>\n          <h3 style=\"font-family:\'Inter Tight\',sans-serif;font-size:16px;font-weight:700;color:#ffffff;margin:0;line-height:1.2;\">IG Reel / Lyrics Clip Maker</h3>\n          <p style=\"font-family:\'Inter Tight\',sans-serif;font-size:12px;color:#64748b;margin:2px 0 0 0;\">Create scroll-stopping lyric videos for Reels</p>\n        </div>\n      </div>\n      <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:8px;\">\n        <li style=\"display:flex;align-items:center;gap:8px;font-family:\'Inter Tight\',sans-serif;color:#cbd5e1;font-size:13px;line-height:1.5;\">\n          <svg style=\"flex-shrink:0;\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n          Animated lyric sequences synced for Reels &amp; short-form video\n        </li>\n        <li style=\"display:flex;align-items:center;gap:8px;font-family:\'Inter Tight\',sans-serif;color:#cbd5e1;font-size:13px;line-height:1.5;\">\n          <svg style=\"flex-shrink:0;\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n          Choose from cinematic, minimal, neon, and karaoke-style visual presets\n        </li>\n        <li style=\"display:flex;align-items:center;gap:8px;font-family:\'Inter Tight\',sans-serif;color:#cbd5e1;font-size:13px;line-height:1.5;\">\n          <svg style=\"flex-shrink:0;\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n          Highlight your favorite verse or chorus with customizable text effects\n        </li>\n        <li style=\"display:flex;align-items:center;gap:8px;font-family:\'Inter Tight\',sans-serif;color:#cbd5e1;font-size:13px;line-height:1.5;\">\n          <svg style=\"flex-shrink:0;\" width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n          Export as video clip — perfect for Instagram Reels, YouTube Shorts &amp; TikTok\n        </li>\n      </ul>\n    </div>\n  </div>\n\n  <!-- 3. Quality Commitment -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg>\n      Our Commitment to Quality\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">Accuracy is at the heart of everything we do at DJYoungster. We understand how frustrating it can be to find incorrect lyrics when you\'re trying to learn a song. That\'s why our team works diligently to verify every lyric we publish. We cross-reference multiple sources, listen to songs repeatedly, and collaborate with native speakers to ensure the highest level of accuracy. When official lyrics are released by artists or music labels, we update our database to reflect the authentic version. We also welcome feedback from our community — if you spot an error, please let us know, and we\'ll make corrections promptly.</p>\n  </div>\n\n  <!-- 4. Our Story -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      Our Story\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">DJYoungster started as a small project driven by a simple frustration: the difficulty of finding accurate song lyrics online, especially for regional Indian languages. What began as a personal collection of favorite songs has evolved into a comprehensive platform serving millions of music enthusiasts. Over the years, we\'ve expanded from a handful of Hindi and Punjabi songs to a vast library covering every major Indian language and English music. Our growth has been fueled by the support of our community — music lovers who share our passion for lyrics and contribute to making DJYoungster better every day.</p>\n  </div>\n\n  <!-- 5. Our Community -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n      Our Community\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">DJYoungster is more than just a lyrics website — it\'s a community for music enthusiasts. Millions of users trust DJYoungster for their daily dose of music and lyrics. We\'re grateful for every visitor who chooses us as their go-to lyrics destination, and we\'re committed to serving you with the best possible experience. We encourage you to explore our collection, discover new music, and connect with songs in ways you never have before. Whether you\'re a casual listener looking up a catchy tune or a dedicated fan wanting to understand every word of your favorite artist\'s latest release, DJYoungster is here for you.</p>\n  </div>\n\n  <!-- 6. Contact Us -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:36px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7\"/></svg>\n      Contact Us\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.6;margin:0 0 14px 0;\">We value your feedback and are always here to help. If you have questions, suggestions, or need assistance, please don\'t hesitate to reach out:</p>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:9px;\">\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/></svg>\n        <span><strong style=\"color:#1e293b;\">Website:</strong> DJYoungster.com</span>\n      </li>\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7\"/></svg>\n        <span><strong style=\"color:#1e293b;\">Email:</strong> <a href=\"mailto:djyoungster32@gmail.com\" style=\"color:#059669;text-decoration:none;font-weight:600;\">djyoungster32@gmail.com</a></span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- Thank You Banner -->\n  <div style=\"background:linear-gradient(135deg,rgba(5,150,105,0.06) 0%,rgba(5,150,105,0.02) 100%);border:1px solid #d1fae5;border-radius:12px;padding:24px 28px;margin-bottom:36px;text-align:center;\">\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:16px;font-weight:600;line-height:1.6;margin:0;\">Thank you for being part of the DJYoungster family.<br><span style=\"color:#059669;\">Together, let\'s celebrate the magic of music!</span></p>\n  </div>\n\n  <!-- Footer -->\n  <div style=\"text-align:center;border-top:1px solid #e2f5ef;padding-top:28px;\">\n    <p style=\"margin:0 0 6px 0;font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:12px;letter-spacing:0.5px;\">Last Updated: January 2026</p>\n    <p style=\"margin:0;font-family:\'Inter Tight\',sans-serif;font-size:18px;font-weight:800;color:#0f172a;letter-spacing:-0.5px;\">DJ<span style=\"color:#059669;\">Youngster</span></p>\n    <p style=\"margin:6px 0 0 0;font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:13px;letter-spacing:1px;text-transform:uppercase;\">Your trusted destination for song lyrics &amp; music information</p>\n  </div>\n\n</section>', 'About Us - DJYoungster | India\'s Trusted Song Lyrics Platform', 'Learn about DJYoungster — your destination for accurate song lyrics in Hindi, Punjabi, Tamil, Telugu & more. Explore our IG Story & Reel creator tools.', 1, '2026-01-30 05:25:30.904', '2026-02-21 07:52:39.534'),
('1f2da61c-dbc6-4b01-92c4-cd66a50b6776', 'disclaimer', 'Disclaimer', '<section style=\"max-width:680px;width:100%;margin:0px auto;position:relative; overflow:hidden;\">\n\n  <!-- Glow blob -->\n  <div style=\"position:absolute;width:300px;height:300px;pointer-events:none;\"></div>\n\n  <!-- Badge -->\n  <div style=\"display:inline-flex;align-items:center;gap:7px;background:rgba(5,150,105,0.08);border:1px solid rgba(5,150,105,0.25);color:#059669;font-family:\'Inter Tight\',sans-serif;font-size:11px;font-weight:600;letter-spacing:2.5px;text-transform:uppercase;padding:6px 14px;border-radius:50px;margin-bottom:28px;\">\n    <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\n    Effective Date: January 2026\n  </div>\n\n  <h1 style=\"font-family:\'Inter Tight\',sans-serif;font-size:clamp(32px,6vw,52px);font-weight:800;color:#0f172a;margin:0 0 16px 0;line-height:1.1;letter-spacing:-1.5px;\">Dis<span style=\"color:#059669;\">claimer</span></h1>\n\n  <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:16px;line-height:1.7;margin:0 0 40px 0;\">The information provided on <strong style=\"color:#1e293b;\">DJYoungster.com</strong> is for general informational and entertainment purposes only. By accessing and using this Website, you acknowledge and agree to the following disclaimer.</p>\n\n  <div style=\"height:1px;background:linear-gradient(to right,transparent,#d1fae5,transparent);margin-bottom:36px;\"></div>\n\n  <!-- 1. General Information -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>\n      1. General Information Disclaimer\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">All content on DJYoungster.com, including song lyrics, translations, romanized text, artist information, and related content, is provided on an \"as is\" and \"as available\" basis for informational and entertainment purposes only. While we strive to provide accurate and up-to-date information, we make no representations or warranties of any kind about the completeness, accuracy, reliability, suitability, or availability of the content.</p>\n  </div>\n\n  <!-- 2. Lyrics Accuracy -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 18V5l12-2v13\"/><circle cx=\"6\" cy=\"18\" r=\"3\"/><circle cx=\"18\" cy=\"16\" r=\"3\"/></svg>\n      2. Lyrics Accuracy Disclaimer\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0 0 12px 0;\">Song lyrics displayed on DJYoungster.com are compiled from various sources for personal, non-commercial use. While we make every effort to ensure accuracy, we cannot guarantee that all lyrics are 100% accurate. Errors may occur due to misinterpretation, transcription errors, or differences between official and released versions.</p>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">If you notice any errors, we encourage you to contact us through our Contact Page so we can review and make necessary corrections.</p>\n  </div>\n\n  <!-- 3. Copyright -->\n  <div style=\"background:#fff8f8;border:1px solid #fecaca;border-left:3px solid #e05555;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#e05555;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>\n      3. Copyright &amp; Intellectual Property\n    </h2>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:12px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Ownership:</strong> DJYoungster does not claim ownership of any song lyrics. All lyrics are the intellectual property of their respective owners and are displayed for educational and personal entertainment purposes.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Copyright Concerns:</strong> If you are a copyright holder and believe any content infringes your rights, please contact us immediately. We will respond promptly and remove or modify content as appropriate.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">No Commercial Use:</strong> Visitors are prohibited from using lyrics from this Website for commercial purposes without obtaining proper licenses from respective copyright holders.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 4. Translation -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m5 8 6 6\"/><path d=\"m4 14 6-6 2-3\"/><path d=\"M2 5h12\"/><path d=\"M7 2h1\"/><path d=\"m22 22-5-10-5 10\"/><path d=\"M14 18h6\"/></svg>\n      4. Translation Disclaimer\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">Translations on DJYoungster.com are intended to convey the general meaning and essence of songs. They are not official and may not perfectly capture every nuance, cultural reference, or artistic intention of the original lyrics. For official translations, please refer to authorized sources or the original artists.</p>\n  </div>\n\n  <!-- 5. Romanization -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"4 7 4 4 20 4 20 7\"/><line x1=\"9\" y1=\"20\" x2=\"15\" y2=\"20\"/><line x1=\"12\" y1=\"4\" x2=\"12\" y2=\"20\"/></svg>\n      5. Romanization Disclaimer\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">Romanized versions of lyrics are provided to help users who cannot read original scripts (such as Devanagari, Tamil, Telugu, etc.) follow along with songs. Romanization systems vary, and our transliterations represent one of several possible ways to write these words in the Latin alphabet.</p>\n  </div>\n\n  <!-- 6. Third-Party Links -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71\"/><path d=\"M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71\"/></svg>\n      6. Third-Party Links Disclaimer\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">DJYoungster.com may contain links to third-party websites, including music streaming platforms and artist pages. These links are for convenience only. We have no control over the content or practices of any third-party websites and assume no responsibility for them. Inclusion of any link does not imply endorsement by DJYoungster.</p>\n  </div>\n\n  <!-- 7. Advertising -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"3\" width=\"20\" height=\"14\" rx=\"2\"/><line x1=\"8\" y1=\"21\" x2=\"16\" y2=\"21\"/><line x1=\"12\" y1=\"17\" x2=\"12\" y2=\"21\"/></svg>\n      7. Advertising Disclaimer\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">DJYoungster.com displays advertisements from third-party networks including Google AdSense. The appearance of advertisements does not constitute an endorsement of the advertised products or services. We are not responsible for content, accuracy, or opinions in any advertisements.</p>\n  </div>\n\n  <!-- 8–9. No Advice + UGC -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n      8–9. No Professional Advice &amp; User Content\n    </h2>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:10px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span>Nothing on DJYoungster.com constitutes professional advice of any kind, including legal, financial, medical, or musical advice. The content is for entertainment and informational purposes only.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span>User-submitted corrections, comments, or other content represent the views of individual contributors and do not necessarily reflect the views of DJYoungster. We reserve the right to remove content that violates our policies.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 10–11. Liability + Indemnification -->\n  <div style=\"background:#fff8f8;border:1px solid #fecaca