linejoin=\"round\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7\"/></svg>\n        <span><strong style=\"color:#1e293b;\">Email:</strong> <a href=\"mailto:djyoungster32@gmail.com\" style=\"color:#059669;text-decoration:none;font-weight:600;\">djyoungster32@gmail.com</a></span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- Footer -->\n  <div style=\"text-align:center;border-top:1px solid #e2f5ef;padding-top:28px;\">\n    <p style=\"margin:0 0 6px 0;font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:12px;letter-spacing:0.5px;\">Last Updated: January 2026</p>\n    <p style=\"margin:0;font-family:\'Inter Tight\',sans-serif;font-size:18px;font-weight:800;color:#0f172a;letter-spacing:-0.5px;\">DJ<span style=\"color:#059669;\">Youngster</span></p>\n    <p style=\"margin:6px 0 0 0;font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:13px;letter-spacing:1px;text-transform:uppercase;\">Your trusted destination for song lyrics &amp; music information</p>\n  </div>\n\n</section>', 'Disclaimer - DJYoungster | Song Lyrics & Content Notice', 'DJYoungster disclaimer on song lyrics accuracy, third-party links, and content usage. All lyrics are property of their respective owners.', 1, '2026-01-30 05:30:17.528', '2026-02-21 07:51:32.143');
