('7192405c-b91f-42cd-9402-625b1d325cdb', 'terms-and-conditions', 'Terms and Conditions', '\n<section style=\"max-width:680px;width:100%;margin:0px auto;position:relative;overflow:hidden;\">\n\n  <!-- Glow blob -->\n  <div style=\"position:absolute;width:300px;height:300px;pointer-events:none;\"></div>\n\n  <!-- Badge -->\n  <div style=\"display:inline-flex;align-items:center;gap:7px;background:rgba(5,150,105,0.08);border:1px solid rgba(5,150,105,0.25);color:#059669;font-family:\'Inter Tight\',sans-serif;font-size:11px;font-weight:600;letter-spacing:2.5px;text-transform:uppercase;padding:6px 14px;border-radius:50px;margin-bottom:28px;\">\n    <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"/><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"/><polyline points=\"10 9 9 9 8 9\"/></svg>\n    Effective Date: January 2026\n  </div>\n\n  <h1 style=\"font-family:\'Inter Tight\',sans-serif;font-size:clamp(32px,6vw,52px);font-weight:800;color:#0f172a;margin:0 0 16px 0;line-height:1.1;letter-spacing:-1.5px;\">Terms &amp; <span style=\"color:#059669;\">Conditions</span></h1>\n\n  <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:16px;line-height:1.7;margin:0 0 40px 0;\">Welcome to <strong style=\"color:#1e293b;\">DJYoungster.com</strong>. By accessing or using our website, you agree to be bound by these Terms and Conditions. Please read them carefully. If you do not agree with any part of these Terms, you must not use our Website.</p>\n\n  <div style=\"height:1px;background:linear-gradient(to right,transparent,#d1fae5,transparent);margin-bottom:36px;\"></div>\n\n  <!-- 1. Acceptance -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg>\n      1. Acceptance of Terms\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">By accessing, browsing, or using DJYoungster.com, you acknowledge that you have read, understood, and agree to be bound by these Terms, along with our Privacy Policy and Disclaimer. We reserve the right to modify these Terms at any time, effective immediately upon posting. Your continued use of the Website after any changes indicates your acceptance of the modified Terms.</p>\n  </div>\n\n  <!-- 2. Description -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 18V5l12-2v13\"/><circle cx=\"6\" cy=\"18\" r=\"3\"/><circle cx=\"18\" cy=\"16\" r=\"3\"/></svg>\n      2. Description of Services\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">DJYoungster provides a platform for users to access song lyrics in multiple languages including Hindi, Punjabi, English, Tamil, Telugu, Bhojpuri, Haryanvi, and other regional languages. Our services include displaying song lyrics, romanized versions, translations, and related information such as artist names, album details, and music credits. All content is provided for informational and entertainment purposes only.</p>\n  </div>\n\n  <!-- 3. Intellectual Property -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M14.31 8l5.74 9.94M9.69 8h11.48M7.38 12l5.74-9.94M9.69 16L3.95 6.06M14.31 16H2.83M16.62 12l-5.74 9.94\"/></svg>\n      3. Intellectual Property Rights\n    </h2>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:12px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Website Content:</strong> The design, layout, graphics, logos, and original written content on DJYoungster.com are the intellectual property of DJYoungster. You may not reproduce, distribute, modify, or create derivative works without our express written permission.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Song Lyrics:</strong> Lyrics displayed are the intellectual property of their respective owners. DJYoungster displays them under fair use principles for educational and personal entertainment. We do not claim ownership of any song lyrics.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">User Restrictions:</strong> You may not use content from this Website for commercial purposes without proper licenses. Systematic downloading, scraping, or bulk copying of lyrics is strictly prohibited.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 4. User Conduct -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n      4. User Conduct\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.6;margin:0 0 14px 0;\">When using DJYoungster.com, you agree to:</p>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:9px;\">\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Use the Website only for lawful purposes and in accordance with these Terms\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Not attempt unauthorized access to any part of the Website, accounts, or connected systems\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Not use automated systems, bots, scrapers, or spiders without our express written permission\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Not transmit viruses, malware, or any other malicious code\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Not impersonate any person or entity or misrepresent your affiliation\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Not interfere with or disrupt the Website or connected servers and networks\n      </li>\n    </ul>\n  </div>\n\n  <!-- 5. User-Generated Content -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7\"/><path d=\"M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z\"/></svg>\n      5. User-Generated Content\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">If we allow users to submit corrections, suggestions, or comments, you grant DJYoungster a non-exclusive, royalty-free, perpetual, irrevocable, and fully sublicensable right to use, reproduce, modify, publish, and distribute such content worldwide in any media. You represent that you own or control all rights to the content you submit and that it does not violate any third party\'s rights.</p>\n  </div>\n\n  <!-- 6. Third-Party + Ads -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71\"/><path d=\"M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71\"/></svg>\n      6. Third-Party Links &amp; Advertisements\n    </h2>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:12px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">External Links:</strong> We have no control over third-party websites linked from our site and assume no responsibility for their content, privacy policies, or practices. DJYoungster shall not be liable for any damage or loss from your use of third-party websites.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Advertisements:</strong> Ads are served through third-party networks including Google AdSense. The presence of advertisements does not constitute an endorsement of advertised products or services. We are not responsible for ad content or any related transactions.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 7. Disclaimer of Warranties -->\n  <div style=\"background:#fff8f8;border:1px solid #fecaca;border-left:3px solid #e05555;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#e05555;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>\n      7. Disclaimer of Warranties\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">DJYoungster.com is provided on an \"as is\" and \"as available\" basis without any warranties of any kind, either express or implied, including implied warranties of merchantability, fitness for a particular purpose, or non-infringement. We do not warrant that the Website will be uninterrupted, error-free, or secure, nor do we guarantee the accuracy, completeness, or timeliness of any content.</p>\n  </div>\n\n  <!-- 8–9. Liability + Indemnification -->\n  <div style=\"background:#fff8f8;border:1px solid #fecaca;border-left:3px solid #e05555;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#e05555;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\" ry=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg>\n      8–9. Limitation of Liability &amp; Indemnification\n    </h2>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:12px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span>To the fullest extent permitted by law, DJYoungster and its affiliates shall not be liable for any indirect, incidental, special, or punitive damages resulting from your access to or use of the Website, any third-party conduct or content, or unauthorized access to your transmissions.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span>You agree to defend, indemnify, and hold harmless DJYoungster and its affiliates from any claims, damages, or expenses arising from your use of the Website, your violation of these Terms, or your infringement of any third-party rights.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 10. Copyright Claims -->\n  <div style=\"background:#fff8f8;border:1px solid #fecaca;border-left:3px solid #e05555;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#e05555;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M14.83 9.17a4 4 0 1 0 0 5.66\"/></svg>\n      10. Copyright Infringement Claims\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.6;margin:0 0 14px 0;\">If you believe any content infringes your copyright, please contact us with the following:</p>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:9px;\">\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Identification of the copyrighted work claimed to be infringed\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Identification of the infringing material and its location on our Website\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Your contact information\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>A statement of good faith belief that the use is not authorized by the copyright owner\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Your physical or electronic signature\n      </li>\n    </ul>\n  </div>\n\n  <!-- 11–13. Termination, Governing Law, Severability -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\n      11–13. Termination, Governing Law &amp; Severability\n    </h2>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:12px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Termination:</strong> We reserve the right to terminate or suspend your access immediately, without prior notice, for any reason including breach of these Terms.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Governing Law:</strong> These Terms are governed by the laws of India. Any disputes shall be subject to the exclusive jurisdiction of the courts located in India.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Severability:</strong> If any provision is found unenforceable, it shall be modified to the minimum extent necessary, and the remaining provisions shall remain in full force and effect.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 14. Entire Agreement -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\n      14. Entire Agreement\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">These Terms, together with our Privacy Policy and Disclaimer, constitute the entire agreement between you and DJYoungster regarding your use of the Website and supersede any prior agreements relating to the Website.</p>\n  </div>\n\n  <!-- 15. Contact -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:36px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7\"/></svg>\n      15. Contact Information\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.6;margin:0 0 14px 0;\">If you have any questions about these Terms and Conditions, please contact us at:</p>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:9px;\">\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/></svg>\n        <span><strong style=\"color:#1e293b;\">Website:</strong> DJYoungster.com</span>\n      </li>\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7\"/></svg>\n        <span><strong style=\"color:#1e293b;\">Email:</strong> <a href=\"mailto:djyoungster32@gmail.com\" style=\"color:#059669;text-decoration:none;font-weight:600;\">djyoungster32@gmail.com</a></span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- Footer -->\n  <div style=\"text-align:center;border-top:1px solid #e2f5ef;padding-top:28px;\">\n    <p style=\"margin:0 0 6px 0;font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:12px;letter-spacing:0.5px;\">Last Updated: January 2026</p>\n    <p style=\"margin:0;font-family:\'Inter Tight\',sans-serif;font-size:18px;font-weight:800;color:#0f172a;letter-spacing:-0.5px;\">DJ<span style=\"color:#059669;\">Youngster</span></p>\n    <p style=\"margin:6px 0 0 0;font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:13px;letter-spacing:1px;text-transform:uppercase;\">Your trusted destination for song lyrics &amp; music information</p>\n  </div>\n\n</section>', 'Terms and Conditions - DJYoungster | Usage & Legal Policy', 'Read DJYoungster\'s Terms and Conditions covering website usage, intellectual property, user conduct, and copyright policies. Effective January 2026.', 1, '2026-01-30 05:29:28.282', '2026-02-21 07:51:52.652');
INSERT INTO `Page` (`id`, `slug`, `title`, `content`, `metaTitle`, `metaDescription`, `isPublished`, `createdAt`, `updatedAt`) VALUES
('7ff7e4da-d767-420c-a74b-4837b92d14ed', 'privacy-policy', 'Privacy Policy', '<section style=\"max-width:680px;width:100%;margin:0px auto;position:relative;overflow:hidden;\">\n\n  <!-- Glow blob -->\n  <div style=\"position:absolute;width:300px;height:300px;pointer-events:none;\"></div>\n\n  <!-- Badge -->\n  <div style=\"display:inline-flex;align-items:center;gap:7px;background:rgba(5,150,105,0.08);border:1px solid rgba(5,150,105,0.25);color:#059669;font-family:\'Inter Tight\',sans-serif;font-size:11px;font-weight:600;letter-spacing:2.5px;text-transform:uppercase;padding:6px 14px;border-radius:50px;margin-bottom:28px;\">\n    <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\n    Effective Date: January 2026\n  </div>\n\n  <h1 style=\"font-family:\'Inter Tight\',sans-serif;font-size:clamp(32px,6vw,52px);font-weight:800;color:#0f172a;margin:0 0 16px 0;line-height:1.1;letter-spacing:-1.5px;\">Privacy <span style=\"color:#059669;\">Policy</span></h1>\n\n  <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:16px;line-height:1.7;margin:0 0 40px 0;\"><strong style=\"color:#1e293b;\">DJYoungster.com</strong> is committed to protecting your privacy. This Privacy Policy explains how we collect, use, disclose, and safeguard your information when you visit our website. By using DJYoungster.com, you consent to the data practices described in this policy.</p>\n\n  <div style=\"height:1px;background:linear-gradient(to right,transparent,#d1fae5,transparent);margin-bottom:36px;\"></div>\n\n  <!-- 1. Information We Collect -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><ellipse cx=\"12\" cy=\"5\" rx=\"9\" ry=\"3\"/><path d=\"M21 12c0 1.66-4 3-9 3s-9-1.34-9-3\"/><path d=\"M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5\"/></svg>\n      1. Information We Collect\n    </h2>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:12px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Voluntarily Provided:</strong> Personal information you provide when contacting us, submitting feedback, or reporting errors — including your name, email address, and any other details you choose to share.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Device &amp; Log Data:</strong> Automatically collected information including your IP address, device type, operating system, browser type, access times, pages viewed, and navigation patterns.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Usage Information:</strong> Information about how you use our Website, including songs you search for, lyrics you view, time spent on pages, and navigation patterns.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Cookies &amp; Tracking:</strong> We use cookies, web beacons, and similar technologies to collect information about your browsing activities. You can control cookies through your browser settings.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 2. How We Use Your Information -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.07 4.93a10 10 0 0 1 0 14.14\"/><path d=\"M4.93 4.93a10 10 0 0 0 0 14.14\"/></svg>\n      2. How We Use Your Information\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.6;margin:0 0 14px 0;\">We use the information we collect to:</p>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:9px;\">\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Provide, maintain, and improve our Website and services\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Respond to your inquiries, comments, feedback, or questions\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Analyze usage patterns and trends to enhance user experience\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Send updates, newsletters, and promotional communications (if opted in)\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Detect, prevent, and address technical issues, fraud, or illegal activities\n      </li>\n      <li style=\"display:flex;align-items:flex-start;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;line-height:1.6;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Serve relevant advertisements through our advertising partners\n      </li>\n    </ul>\n  </div>\n\n  <!-- 3. Advertising & Third-Party -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"3\" width=\"20\" height=\"14\" rx=\"2\"/><line x1=\"8\" y1=\"21\" x2=\"16\" y2=\"21\"/><line x1=\"12\" y1=\"17\" x2=\"12\" y2=\"21\"/></svg>\n      3. Advertising &amp; Third-Party Services\n    </h2>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:12px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Google AdSense:</strong> We use Google AdSense to display ads. It uses cookies to serve ads based on your prior visits. You can opt out of personalized advertising via Google\'s Ads Settings.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Google Analytics:</strong> We use Google Analytics to analyze site traffic. It collects data on visitor behavior to help us improve our Website. You can opt out via the Google Analytics Opt-out Browser Add-on.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Other Services:</strong> We may use social media plugins, embedded content, and other analytics tools. These third parties may collect information when you interact with their features on our Website.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 4. Cookies Policy -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5\"/><path d=\"M8.5 8.5v.01\"/><path d=\"M16 15.5v.01\"/><path d=\"M12 12v.01\"/><path d=\"M11 17v.01\"/><path d=\"M7 14v.01\"/></svg>\n      4. Cookies Policy\n    </h2>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:12px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Essential Cookies:</strong> Necessary for the Website to function properly. Cannot be switched off and are set in response to actions you take.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Performance Cookies:</strong> Help us count visits and traffic sources to measure and improve Website performance, understanding popular pages and navigation patterns.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Functional Cookies:</strong> Enable enhanced functionality and personalization, such as remembering your preferences and settings.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Advertising Cookies:</strong> Set by our advertising partners to build interest profiles and show relevant ads on other websites. You can manage preferences through your browser settings.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 5. Data Sharing -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8\"/><polyline points=\"16 6 12 2 8 6\"/><line x1=\"12\" y1=\"2\" x2=\"12\" y2=\"15\"/></svg>\n      5. Data Sharing &amp; Disclosure\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.6;margin:0 0 14px 0;\">We do not sell, trade, or rent your personal information to third parties. We may share your information only in these circumstances:</p>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:10px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Service Providers:</strong> Third parties who perform services on our behalf (hosting, analytics, advertising) with access limited to performing those services.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Legal Requirements:</strong> When required by law or in response to valid requests by public authorities such as a court or government agency.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Business Transfers:</strong> In the event of a merger, acquisition, or asset sale, your information may be transferred as part of that transaction.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Protection of Rights:</strong> To protect our rights or property, user safety, or to prevent illegal or unethical activity.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 6–7. Security + Retention -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\" ry=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg>\n      6–7. Data Security &amp; Retention\n    </h2>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:12px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span>We implement appropriate technical and organizational measures to protect your personal information. However, no method of transmission over the Internet is completely secure and we cannot guarantee absolute security.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span>We retain your personal information only as long as necessary to fulfill the purposes for which it was collected, including legal, accounting, or reporting requirements. When no longer needed, we securely delete or anonymize it.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 8. Your Rights -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><polyline points=\"23 11 17 11\"/><line x1=\"20\" y1=\"8\" x2=\"20\" y2=\"14\"/></svg>\n      8. Your Rights &amp; Choices\n    </h2>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:10px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Access &amp; Correction:</strong> You have the right to request access to and correction of personal information we hold about you.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Deletion:</strong> You may request deletion of your personal information, subject to certain exceptions provided by law.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Opt-Out:</strong> You may opt out of promotional communications by following the unsubscribe instructions included in those emails, or opt out of personalized advertising as described in Section 3.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span><strong style=\"color:#334155;\">Do Not Track:</strong> Our Website does not currently respond to browser \"Do Not Track\" signals.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 9–10. Children + International -->\n  <div style=\"background:#fff8f8;border:1px solid #fecaca;border-left:3px solid #e05555;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#e05555;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>\n      9–10. Children\'s Privacy &amp; International Transfers\n    </h2>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:12px;\">\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span>DJYoungster.com is not directed to children under the age of 13, and we do not knowingly collect personal information from children under 13. If we become aware of such collection, we will take steps to delete that information immediately.</span>\n      </li>\n      <li style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:14px;line-height:1.6;display:flex;gap:10px;align-items:flex-start;\">\n        <svg style=\"flex-shrink:0;margin-top:3px;\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span>Your information may be transferred to and processed in countries other than your country of residence with different data protection laws. By using our Website, you consent to such transfers.</span>\n      </li>\n    </ul>\n  </div>\n\n  <!-- 11. Changes -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7\"/><path d=\"M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z\"/></svg>\n      11. Changes to This Privacy Policy\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0;\">We may update this Privacy Policy from time to time. We will notify you of material changes by posting the new policy on this page and updating the Effective Date. We encourage you to review this Privacy Policy periodically to stay informed about how we protect your information.</p>\n  </div>\n\n  <!-- 12. Contact -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:36px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7\"/></svg>\n      12. Contact Us\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.6;margin:0 0 14px 0;\">If you have any questions, concerns, or requests regarding this Privacy Policy or our data practices, please contact us at:</p>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:9px;\">\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/></svg>\n        <span><strong style=\"color:#1e293b;\">Website:</strong> DJYoungster.com</span>\n      </li>\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7\"/></svg>\n        <span><strong style=\"color:#1e293b;\">Email:</strong> <a href=\"mailto:djyoungster32@gmail.com\" style=\"color:#059669;text-decoration:none;font-weight:600;\">djyoungster32@gmail.com</a></span>\n      </li>\n    </ul>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:13px;margin:16px 0 0 0;padding:12px 14px;background:rgba(5,150,105,0.05);border-radius:8px;border:1px solid rgba(5,150,105,0.15);\">By using our Website, you hereby consent to our Privacy Policy and agree to its terms.</p>\n  </div>\n\n  <!-- Footer -->\n  <div style=\"text-align:center;border-top:1px solid #e2f5ef;padding-top:28px;\">\n    <p style=\"margin:0 0 6px 0;font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:12px;letter-spacing:0.5px;\">Last Updated: January 2026</p>\n    <p style=\"margin:0;font-family:\'Inter Tight\',sans-serif;font-size:18px;font-weight:800;color:#0f172a;letter-spacing:-0.5px;\">DJ<span style=\"color:#059669;\">Youngster</span></p>\n    <p style=\"margin:6px 0 0 0;font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:13px;letter-spacing:1px;text-transform:uppercase;\">Your trusted destination for song lyrics &amp; music information</p>\n  </div>\n\n</section>', 'Privacy Policy - DJYoungster | How We Protect Your Data', 'DJYoungster\'s Privacy Policy explains how we collect, use, and protect your data. Learn about cookies, third-party ads, and your privacy rights.', 1, '2026-01-30 05:27:40.008', '2026-02-21 07:52:17.760'),
('d7d041f5-d165-4872-ada8-3686d78a3da6', 'contact-us', 'Contact Us', '<link href=\"https://fonts.googleapis.com/css2?family=Inter+Tight:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n\n<section style=\"max-width:680px;width:100%;margin:0px auto;position:relative;overflow:hidden;\">\n\n  <!-- Glow blob -->\n  <div style=\"position:absolute;width:500px;height:300px;pointer-events:none;\"></div>\n\n  <!-- Badge -->\n  <div style=\"display:inline-flex;align-items:center;gap:7px;background:rgba(5,150,105,0.08);border:1px solid rgba(5,150,105,0.25);color:#059669;font-family:\'Inter Tight\',sans-serif;font-size:11px;font-weight:600;letter-spacing:2.5px;text-transform:uppercase;padding:6px 14px;border-radius:50px;margin-bottom:28px;\">\n    <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 18V5l12-2v13\"/><circle cx=\"6\" cy=\"18\" r=\"3\"/><circle cx=\"18\" cy=\"16\" r=\"3\"/></svg>\n    Get In Touch\n  </div>\n\n  <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:16px;line-height:1.7;margin:0 0 12px 0;\">Have a question, suggestion, or found something that needs correction? We\'re always happy to hear from you.</p>\n  <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.7;margin:0 0 40px 0;\"><strong style=\"color:#1e293b;\">DJYoungster</strong> is a song lyrics platform dedicated to providing accurate and up-to-date lyrics across multiple languages. If you notice any errors in lyrics, metadata, or translations, or if you have general feedback, feel free to reach out.</p>\n\n  <div style=\"height:1px;background:linear-gradient(to right,transparent,#d1fae5,transparent);margin-bottom:36px;\"></div>\n\n  <!-- Email Card -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7\"/></svg>\n      Email\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.6;margin:0 0 12px 0;\">For all inquiries, corrections, or support, contact us at:</p>\n    <a href=\"mailto:djyoungster32@gmail.com\" style=\"display:inline-flex;align-items:center;gap:8px;background:linear-gradient(135deg,#059669,#047857);color:#ffffff;font-family:\'Inter Tight\',sans-serif;font-weight:700;font-size:15px;text-decoration:none;padding:10px 22px;border-radius:8px;letter-spacing:0.2px;\">\n      <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7\"/></svg>\n      djyoungster32@gmail.com\n    </a>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:13px;margin:14px 0 0 0;display:flex;align-items:center;gap:6px;\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#94a3b8\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\n      We usually respond within <strong style=\"color:#64748b;\">24–48 hours</strong>.\n    </p>\n  </div>\n\n  <!-- Lyrics Corrections Card -->\n  <div style=\"background:#f8fffe;border:1px solid #d1fae5;border-left:3px solid #059669;border-radius:12px;padding:24px 28px;margin-bottom:24px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#059669;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7\"/><path d=\"M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z\"/></svg>\n      Lyrics Corrections &amp; Requests\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.6;margin:0 0 14px 0;\">If you\'re reporting a correction, please include:</p>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:9px;\">\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Song name\n      </li>\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Artist name\n      </li>\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Language\n      </li>\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>The correction or update required\n      </li>\n    </ul>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:13px;margin:14px 0 0 0;\">This helps us resolve issues faster.</p>\n  </div>\n\n  <!-- Copyright Card -->\n  <div style=\"background:#fff8f8;border:1px solid #fecaca;border-left:3px solid #e05555;border-radius:12px;padding:24px 28px;margin-bottom:36px;\">\n    <h2 style=\"font-family:\'Inter Tight\',sans-serif;font-size:17px;font-weight:700;color:#e05555;margin:0 0 10px 0;display:flex;align-items:center;gap:8px;\">\n      <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>\n      Copyright &amp; Content Concerns\n    </h2>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#64748b;font-size:15px;line-height:1.6;margin:0 0 14px 0;\">If you are a copyright owner or represent one and believe any content on DJYoungster infringes your rights, please email us with:</p>\n    <ul style=\"margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:9px;\">\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>The specific URL(s)\n      </li>\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Proof of ownership\n      </li>\n      <li style=\"display:flex;align-items:center;gap:10px;font-family:\'Inter Tight\',sans-serif;color:#334155;font-size:14px;\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#e05555\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Your contact details\n      </li>\n    </ul>\n    <p style=\"font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:13px;margin:14px 0 0 0;\">We take copyright concerns seriously and will act promptly.</p>\n  </div>\n\n  <!-- Footer -->\n  <div style=\"text-align:center;border-top:1px solid #e2f5ef;padding-top:28px;\">\n    <p style=\"margin:0;font-family:\'Inter Tight\',sans-serif;font-size:18px;font-weight:800;color:#0f172a;letter-spacing:-0.5px;\">DJ<span style=\"color:#059669;\">Youngster</span></p>\n    <p style=\"margin:6px 0 0 0;font-family:\'Inter Tight\',sans-serif;color:#94a3b8;font-size:13px;letter-spacing:1px;text-transform:uppercase;\">Your trusted destination for song lyrics &amp; music information</p>\n  </div>\n\n</section>', 'Contact Us - DJYoungster | Get in Touch for Lyrics Support', 'Have questions or feedback? Contact DJYoungster for lyrics requests, copyright inquiries, or support. We\'re here to help music lovers across India.', 1, '2026-02-05 04:57:42.269', '2026-02-21 07:51:09.392');
