('009cccaa-6e06-4622-9fd3-8ab0c0241432', 'global', 'Global Settings', 'Global Site Settings', NULL, '{\"favicon\":\"/uploads/1769697405737-djyoungster.webp\",\"heroHeading\":\"DJYoungster - India\'s #1 *Lyrics Platform*\",\"heroDescription\":\"Whether it\'s a Punjabi anthem or a Tamil melody, DJYoungster brings you the complete lyrics in the language you love. Pick lines, create status, and share the vibe.\",\"ogImage\":\"/uploads/1769674444129-djyoungster.webp\"}', NULL, NULL, '2026-01-28 07:54:05.877', '2026-02-18 05:18:57.869', NULL),
('263dace6-a083-4c2e-9968-87c7b05421da', 'homepage', 'Homepage', 'DJYoungster – Lyrics, Meanings & Instagram Status Maker', 'DJYoungster is India\'s multilingual lyrics platform. Read, share & create lyrics stories for Instagram & WhatsApp. Hindi, Punjabi, Tamil, Telugu songs lyrics with meanings. Free.', 'song lyrics, hindi lyrics, punjabi lyrics, english lyrics, bollywood songs', 'DJYoungster - India\'s Largest Multilingual Song\'s Lyrics Collection', 'From Punjabi beats to Tamil melodies — find accurate lyrics for thousands of songs across 6+ languages. Updated with every new release.', '2026-01-27 21:17:48.075', '2026-02-20 03:25:25.361', '/uploads/1771515290796-1769667605411-djyoungster.webp'),
('4cb78fb7-9fc2-4a0b-9c45-2d4c21e34b26', 'movies', 'All Movies', 'Movie Songs 2026 & Soundtracks - All Films | DJYoungster', 'Browse latest movies 2026 on DJYoungster. Find Bollywood, Punjabi, Hollywood, Tamil & Telugu movie song lyrics with complete soundtrack, tracklist & album details.', 'latest movies, new movies, Bollywood movies, Punjabi movies, Hollywood movies, Tamil movies, Telugu movies, movie song lyrics, film soundtracks, movie albums, new film songs, DJYoungster movies', 'Movie Songs 2026 & Soundtracks - All Films | DJYoungster', 'Browse latest movies 2026 on DJYoungster. Find Bollywood, Punjabi, Hollywood, Tamil & Telugu movie song lyrics with complete soundtrack, tracklist & album details.', '2026-01-30 05:42:36.459', '2026-01-30 05:42:36.459', NULL),
('92b56326-24d0-4c21-8cd1-8047c6151f47', 'genres', 'All Genres', 'Music Genres 2026 - Browse Songs by Genre | DJYoungster', 'Explore all music genres 2026 on DJYoungster. Browse song lyrics by genre including Pop, Rock, Hip Hop, Romantic, Sad, Devotional, Party songs & more categories.', 'music genres, song genres, browse by genre, Pop songs lyrics, Rock songs, Hip Hop lyrics, Romantic songs, Sad songs lyrics, Devotional songs, Party songs, Bollywood genres, Punjabi song genres, DJYoungster genres', 'Music Genres 2026 - Browse Songs by Genre | DJYoungster', 'Explore all music genres 2026 on DJYoungster. Browse song lyrics by genre including Pop, Rock, Hip Hop, Romantic, Sad, Devotional, Party songs & more categories.', '2026-01-30 05:41:27.126', '2026-01-30 05:41:27.126', NULL),
